import json,re,collections,xml.etree.ElementTree as ET
from html import unescape
from pathlib import Path
s=json.load(open('source.json'));a=json.load(open('answer.json'));r=json.load(open('reference-targets.json'))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
classes={'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
units={'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
def plain(x):return re.sub(r'\\s+',' ',unescape(re.sub(r'<["'^>]+>'"',' ',x))).strip()
assert len(a)==len(s)==24
for src,out in zip(s,a):
 n=out['number']
 for k in ['code_id','source_id','source_sha256','number']:assert out[k]==src[k],(n,k)
 assert all(k in out for k in ['proposed_xml','reason','review_notes','status','substantive_impact'])
 si=out['substantive_impact'];assert si['version']==1 and si['classification'] in classes
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(si[k])>=40,(n,k)
 if out['status']=='retained_unchanged':
  assert out['proposed_xml'] is None and si['effects']==[] and out['classification']==si['classification']=='retained_necessary'
 else:
  x=out['proposed_xml'];assert isinstance(x,str) and x"'!=src['"'source_xml']
  root=ET.fromstring('<root>'+x+'</root>')
  for el in root.iter():
   if el.tag=='root':continue
   assert el.tag in allowed,(n,el.tag)
   assert all(k in ['rowspan','colspan'] and v.isdigit() for k,v in el.attrib.items()),(n,el.attrib)
  if out.get('change_type')=='normative_reduction':
   assert out['reform_policy_id']=='editorial_direction_2026_10_19'
   assert out['removed_provisions'] and all(len(x)>=30 for x in out['removed_provisions'])
  for e in si['effects']:
   assert e['kind'] in kinds and e['unit'] in units
   assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
   for k in ['description','before','after','affected_population','conditions_and_transition','replacement_or_new_burdens']:assert e[k]
   for q,body in [('source_quote',src['source_xml']),('proposed_quote',x)]:
    assert len(e[q])>=12 and e[q] in plain(body),(n,q,e[q])
 req=r['requirements'][src['code_id']+'|'+src['source_id']]
 assert [c['target_key'] for c in out['reference_checks']]==req,n
 for c in out['reference_checks']:
  assert c['view_sha256']==r['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80,n
 if src.get('benefit_check_required'):assert len(out['benefit_review'])>=100
 print(n, out['status'], si['classification'], 'refs',len(req),'effects',len(si['effects']))
print('VALIDATION OK',collections.Counter(x['status'] for x in a),'size',Path('answer.json').stat().st_size)
PY"

